package core.domain.aggregate;

import core.domain.event.NoteCreated;
import core.domain.valueobject.NoteId;
import java.util.Objects;
import lombok.Getter;
import ru.vikulinva.ddd.AggregateRoot;

@Getter
public class Note extends AggregateRoot<NoteId> {
  private final NoteId id;
  private final String text;

  private Note(NoteId id, String text) {
    this.id = Objects.requireNonNull(id, "id must not be null");
    if (text == null || text.isBlank()) {
      throw new IllegalArgumentException("text must not be blank");
    }
    this.text = text;
  }

  public static Note create(NoteId id, String text) {
    Note note = new Note(id, text);
    note.markCreated();
    return note;
  }

  public static Note restore(NoteId id, String text) {
    return new Note(id, text);
  }

  private void markCreated() {
    registerEvent(new NoteCreated(id, text));
  }
}

